import winston from 'winston';
import DailyRotateFile from 'winston-daily-rotate-file';
import path from 'path';

// Define log format
const logFormat = winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    winston.format.errors({ stack: true }),
    winston.format.splat(),
    winston.format.json()
);

// Console format (pretty for development)
const consoleFormat = winston.format.combine(
    winston.format.colorize(),
    winston.format.timestamp({ format: 'HH:mm:ss' }),
    winston.format.printf(({ timestamp, level, message, ...meta }) => {
        let msg = `${timestamp} [${level}]: ${message}`;
        if (Object.keys(meta).length > 0) {
            msg += ` ${JSON.stringify(meta)}`;
        }
        return msg;
    })
);

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, '../../logs');

// Define transports
const transports: winston.transport[] = [
    // Console transport (always enabled)
    new winston.transports.Console({
        format: consoleFormat,
        level: process.env.NODE_ENV === 'production' ? 'info' : 'debug'
    })
];

// File transports (only in production or if explicitly enabled)
if (process.env.NODE_ENV === 'production' || process.env.ENABLE_FILE_LOGGING === 'true') {
    // Error log file
    transports.push(
        new DailyRotateFile({
            dirname: logsDir,
            filename: 'error-%DATE%.log',
            datePattern: 'YYYY-MM-DD',
            level: 'error',
            maxFiles: '30d',
            maxSize: '20m',
            format: logFormat
        })
    );

    // Combined log file
    transports.push(
        new DailyRotateFile({
            dirname: logsDir,
            filename: 'combined-%DATE%.log',
            datePattern: 'YYYY-MM-DD',
            maxFiles: '14d',
            maxSize: '20m',
            format: logFormat
        })
    );
}

// Create logger instance
export const logger = winston.createLogger({
    level: process.env.LOG_LEVEL || 'info',
    format: logFormat,
    transports,
    exitOnError: false
});

// Create stream for Morgan
export const loggerStream = {
    write: (message: string) => {
        logger.info(message.trim());
    }
};

// Helper functions for common log patterns
export const logError = (error: Error, context?: string) => {
    logger.error({
        message: error.message,
        stack: error.stack,
        context
    });
};

export const logRequest = (method: string, url: string, statusCode: number, duration: number) => {
    logger.http({
        method,
        url,
        statusCode,
        duration: `${duration}ms`
    });
};

export const logAudit = (action: string, user: string, details?: any) => {
    logger.info({
        type: 'AUDIT',
        action,
        user,
        details,
        timestamp: new Date().toISOString()
    });
};

export default logger;

import Redis from 'ioredis';
import { logger } from './logger';

let redisClient: Redis | null = null;
let isRedisAvailable = false;

/**
 * Initialize Redis connection
 */
export function initRedis(): Redis | null {
    // If Redis is disabled or already initialized, return
    if (process.env.REDIS_ENABLED === 'false') {
        logger.info('⚠️ Redis is disabled via environment variable');
        return null;
    }

    if (redisClient) {
        return redisClient;
    }

    try {
        const redisUrl = process.env.REDIS_URL || 'redis://localhost:6379';

        redisClient = new Redis(redisUrl, {
            retryStrategy: (times) => {
                const delay = Math.min(times * 50, 2000);
                return delay;
            },
            maxRetriesPerRequest: 3,
            enableReadyCheck: true,
            lazyConnect: true, // Don't connect immediately
        });

        // Connect manually to handle errors
        redisClient.connect().then(() => {
            logger.info('✅ Redis connected successfully');
            isRedisAvailable = true;
        }).catch((error) => {
            logger.warn('⚠️ Redis connection failed. Running without cache:', error.message);
            isRedisAvailable = false;
            redisClient = null;
        });

        // Handle connection errors
        redisClient.on('error', (error) => {
            logger.warn('⚠️ Redis error:', error.message);
            isRedisAvailable = false;
        });

        // Handle reconnection
        redisClient.on('connect', () => {
            logger.info('✅ Redis reconnected');
            isRedisAvailable = true;
        });

        return redisClient;
    } catch (error) {
        logger.error('⚠️ Failed to initialize Redis:', error);
        return null;
    }
}

/**
 * Get Redis client instance
 */
export function getRedisClient(): Redis | null {
    return redisClient;
}

/**
 * Check if Redis is available
 */
export function isRedisReady(): boolean {
    return isRedisAvailable && redisClient !== null;
}

/**
 * Set cache with TTL
 */
export async function setCache(key: string, value: any, ttlSeconds: number = 300): Promise<void> {
    if (!isRedisReady()) return;

    try {
        const serialized = JSON.stringify(value);
        await redisClient!.setex(key, ttlSeconds, serialized);
    } catch (error) {
        logger.warn('⚠️ Failed to set cache:', error);
    }
}

/**
 * Get cache
 */
export async function getCache<T>(key: string): Promise<T | null> {
    if (!isRedisReady()) return null;

    try {
        const cached = await redisClient!.get(key);
        if (!cached) return null;

        return JSON.parse(cached) as T;
    } catch (error) {
        logger.warn('⚠️ Failed to get cache:', error);
        return null;
    }
}

/**
 * Delete cache
 */
export async function deleteCache(key: string): Promise<void> {
    if (!isRedisReady()) return;

    try {
        await redisClient!.del(key);
    } catch (error) {
        logger.warn('⚠️ Failed to delete cache:', error);
    }
}

/**
 * Delete cache by pattern
 */
export async function deleteCachePattern(pattern: string): Promise<void> {
    if (!isRedisReady()) return;

    try {
        const keys = await redisClient!.keys(pattern);
        if (keys.length > 0) {
            await redisClient!.del(...keys);
        }
    } catch (error) {
        logger.warn('⚠️ Failed to delete cache pattern:', error);
    }
}

/**
 * Clear all cache
 */
export async function clearAllCache(): Promise<void> {
    if (!isRedisReady()) return;

    try {
        await redisClient!.flushdb();
        logger.info('✅ All cache cleared');
    } catch (error) {
        logger.warn('⚠️ Failed to clear all cache:', error);
    }
}

/**
 * Close Redis connection
 */
export async function closeRedis(): Promise<void> {
    if (redisClient) {
        await redisClient.quit();
        redisClient = null;
        isRedisAvailable = false;
        logger.info('✅ Redis connection closed');
    }
}

import { Request, Response } from 'express';
import { Order } from '../models/Order';
import { OrderItem } from '../models/OrderItem';
import path from 'path';
import fs from 'fs';
import { logger } from '../config/logger';
import { sendError } from '../middleware/errorHandler';

function maskEmail(email?: string): string {
    if (!email || !email.includes('@')) return '';
    const parts = email.split('@');
    const local = parts[0] ?? '';
    const domain = parts[1] ?? '';
    if (local.length <= 2) return `***@${domain}`;
    return `${local.slice(0, 1)}${'*'.repeat(local.length - 2)}${local.slice(-1)}@${domain}`;
}

function sendInvoiceFile(order: Order, res: Response) {
    if (!order.invoice_file) {
        return res.status(404).json({
            error: 'Comprobante aún no disponible',
            message: 'El comprobante será generado una vez que se verifique el pago'
        });
    }

    const filepath = path.join(__dirname, '../../uploads/invoices', order.invoice_file);

    if (!fs.existsSync(filepath)) {
        return res.status(404).json({ error: 'Archivo de comprobante no encontrado' });
    }

    return res.download(filepath, order.invoice_file, (err) => {
        if (err) {
            logger.error('Error downloading invoice:', err);
            if (!res.headersSent) {
                return sendError(res, err, 'Error al descargar comprobante');
            }
        }
    });
}

// Obtener pedido por código de seguimiento (público, payload reducido)
export const getOrderByTrackingCode = async (req: Request, res: Response) => {
    try {
        const { code } = req.params;

        const order = await Order.findOne({
            where: { tracking_code: code },
            include: [{ model: OrderItem, as: 'items' }]
        });

        if (!order) {
            return res.status(404).json({ error: 'Pedido no encontrado' });
        }

        res.json({
            id: order.id,
            tracking_code: order.tracking_code,
            customer_name: order.customer_name,
            customer_email: maskEmail(order.customer_email),
            total_amount: order.total_amount,
            status: order.status,
            payment_status: order.payment_status,
            payment_method: order.payment_method,
            invoice_type: order.invoice_type,
            invoice_number: order.invoice_number,
            has_invoice: !!order.invoice_file,
            items: (order as any).items.map((item: any) => ({
                product_name: item.product_name,
                quantity: item.quantity,
                price: item.price
            })),
            createdAt: order.createdAt
        });
    } catch (error) {
        logger.error('Error getting order by tracking code:', error);
        return sendError(res, error, 'Error al obtener pedido');
    }
};

// Descargar comprobante por código de seguimiento (público, requiere el código secreto)
export const downloadInvoiceByTrackingCode = async (req: Request, res: Response) => {
    try {
        const { code } = req.params;
        const order = await Order.findOne({ where: { tracking_code: code } });

        if (!order) {
            return res.status(404).json({ error: 'Pedido no encontrado' });
        }

        return sendInvoiceFile(order, res);
    } catch (error) {
        logger.error('Error downloading invoice by tracking code:', error);
        return sendError(res, error, 'Error al descargar comprobante');
    }
};

import { Request, Response } from 'express';
import { PeruanaInformaticaService } from '../services/PeruanaInformaticaService';
import { sendError } from '../middleware/errorHandler';

export const consultArticle = async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        if (!id) {
            return res.status(400).json({ error: 'Se requiere el ID del artículo' });
        }

        const data = await PeruanaInformaticaService.consultarArticulo(id);

        if (!data) {
            return res.status(404).json({ error: 'Artículo no encontrado o respuesta inválida del servidor externo' });
        }

        res.json(data);
    } catch (error: any) {
        return sendError(res, error, 'Error interno al consultar la API externa');
    }
};

import { Request, Response } from 'express';
import { Product, type ProductAttributes } from '../models/Product';
import { SubCategory } from '../models/SubCategory';
import { ProductSubCategory } from '../models/ProductSubCategory';
import { Op, Sequelize, type Includeable, type IncludeOptions, type WhereOptions } from 'sequelize';
import { logger } from '../config/logger';
import { sendError } from '../middleware/errorHandler';

const extractComponentSpecs = (product: { description?: string | null }) => {
  const description = product.description || '';
  const cleanDescription = description.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

  let processor = 'No especificado';
  const processorPatterns = [
    /(Intel\s+Core\s+i[3579]-?\d+[A-Z]*)/i,
    /(AMD\s+Ryzen\s+\d+\s*\d*)/i,
    /(Intel\s+Celeron|Intel\s+Pentium)/i,
    /(Apple\s+M\d+\s+Chip)/i,
    /(Intel\s+Core)/i,
    /(AMD\s+Ryzen)/i
  ];

  for (const pattern of processorPatterns) {
    const match = cleanDescription.match(pattern);
    if (match) {
      processor = match[0].replace(/\s+/g, ' ').trim();
      break;
    }
  }

  let ram = 'No especificado';
  const ramMatch = cleanDescription.match(/(\d+)\s*(GB|GB DDR4|GB DDR5|GB RAM)/i);
  if (ramMatch) {
    ram = ramMatch[0].trim();
  }

  let storage = 'No especificado';
  const storagePatterns = [
    /(\d+)\s*(GB|TB)\s*(SSD|HDD|NVMe)/i,
    /Disco\s+S[oó]lido\s+de\s+(\d+)\s*(GB|TB)/i,
    /(\d+)\s*(GB|TB)\s+de\s+almacenamiento/i
  ];

  for (const pattern of storagePatterns) {
    const match = cleanDescription.match(pattern);
    if (match) {
      storage = match[0].replace(/Disco\s+S[oó]lido\s+de\s+/i, '').replace(/de\s+almacenamiento/i, '').trim();
      break;
    }
  }

  let graphics = 'No especificado';
  if (cleanDescription.includes('GTX') || cleanDescription.includes('RTX')) {
    graphics = 'Dedicada';
  } else if (cleanDescription.includes('Intel') || cleanDescription.includes('AMD') || cleanDescription.includes('integrada')) {
    graphics = 'Integrada';
  }

  let screenSize = 'No especificado';
  const screenMatch = cleanDescription.match(/(\d+\.?\d*)[""]/);
  if (screenMatch) {
    screenSize = screenMatch[0];
  }

  return {
    processor,
    ram,
    storage,
    graphics,
    screen_size: screenSize
  };
};

export const getLaptopsWithSubcategories = async (req: Request, res: Response) => {
  try {
    const { subcategory, minPrice, maxPrice, search } = req.query;

    let orConditions: WhereOptions<ProductAttributes>[] = [
      { category_id: 1 },
      { name: { [Op.like]: '%laptop%' } },
      { name: { [Op.like]: '%Laptop%' } }
    ];

    if (search) {
      orConditions = [
        { name: { [Op.like]: '%${search}%' } },
        { description: { [Op.like]: '%${search}%' } }
      ];
    }

    const subCategoryInclude: IncludeOptions = {
      model: SubCategory,
      as: 'subCategories',
      attributes: ['id', 'name', 'slug'],
      through: { attributes: [] },
      required: false
    };

    if (subcategory) {
      subCategoryInclude.required = true;
      subCategoryInclude.where = {
        slug: subcategory as string
      };
    }

    const includeConditions: Includeable[] = [subCategoryInclude];

    const { processor, ram, storage } = req.query;
    const andConditions: ReturnType<typeof Sequelize.literal>[] = [];

    const addSubcategoryFilter = (slug: string) => {
      const sanitizedSlug = slug.replace(/[^a-zA-Z0-9-]/g, '');

      andConditions.push(Sequelize.literal(`
        EXISTS (
          SELECT 1 
          FROM product_sub_categories psc
          JOIN sub_categories sc ON psc.sub_category_id = sc.id
          WHERE psc.product_codigo_interno = Product.codigo_interno
          AND sc.slug = '${sanitizedSlug}'
        )
      `));
    };

    if (processor) addSubcategoryFilter(processor as string);
    if (ram) addSubcategoryFilter(ram as string);
    if (storage) addSubcategoryFilter(storage as string);

    const whereClause: WhereOptions<ProductAttributes> = {
      [Op.or]: orConditions,
      [Op.and]: andConditions,
      is_active: true,
      stock: { [Op.gt]: 0 },
      ...(minPrice || maxPrice ? {
        price: {
          ...(minPrice ? { [Op.gte]: parseFloat(minPrice as string) } : {}),
          ...(maxPrice ? { [Op.lte]: parseFloat(maxPrice as string) } : {})
        }
      } : {})
    };

    const laptops = await Product.findAll({
      where: whereClause,
      include: includeConditions,
      order: [['price', 'ASC']]
    });

    const laptopsWithSpecs = laptops.map(laptop => {
      const laptopData: ProductAttributes = laptop.toJSON();

      if (laptopData.component_specs && Object.keys(laptopData.component_specs).length > 0) {
        return laptopData;
      }

      laptopData.component_specs = extractComponentSpecs(laptopData);
      return laptopData;
    });

    res.json(laptopsWithSpecs);
  } catch (error) {
    logger.error('Error fetching laptops with subcategories:', error);
    return sendError(res, error, 'Error interno');
  }
};

