import { Request, Response } from "express";
import { SeoSettings } from "../models/SeoSettings";
import { sendError } from '../middleware/errorHandler';

export class SeoAnalysisController {
  static async getSeoAnalysis(req: Request, res: Response) {
    try {
      const allSettings = await SeoSettings.findAll({
        where: { is_active: true },
      });

      const analysis = {
        totalPages: allSettings.length,
        optimizedPages: 0,
        pagesNeedingAttention: 0,
        missingMetaTitle: 0,
        missingMetaDescription: 0,
        missingKeywords: 0,
        incompleteOpenGraph: 0,
        incompleteTwitter: 0,
        pagesByType: {} as any,
        recommendations: [] as string[],
      };

      analysis.recommendations = [];

      // Detalles de páginas con problemas
      const pagesWithIssues: any[] = [];

      // Analizar cada configuración
      allSettings.forEach((setting) => {
        let needsAttention = false;
        const issues: string[] = [];

        // Contar por tipo de página
        if (!analysis.pagesByType[setting.page_type]) {
          analysis.pagesByType[setting.page_type] = 0;
        }
        analysis.pagesByType[setting.page_type]++;

        // Verificar meta título
        if (!setting.meta_title) {
          analysis.missingMetaTitle++;
          needsAttention = true;
          issues.push("Falta título meta");
        } else if (setting.meta_title.length < 30 || setting.meta_title.length > 60) {
          issues.push("Longitud de título meta no óptima (30-60 caracteres)");
          needsAttention = true;
        }

        // Verificar meta descripción
        if (!setting.meta_description) {
          analysis.missingMetaDescription++;
          needsAttention = true;
          issues.push("Falta descripción meta");
        } else if (setting.meta_description.length < 120 || setting.meta_description.length > 160) {
          issues.push("Longitud de descripción meta no óptima (120-160 caracteres)");
          needsAttention = true;
        }

        // Verificar keywords
        if (!setting.meta_keywords) {
          analysis.missingKeywords++;
          needsAttention = true;
          issues.push("Faltan palabras clave");
        }

        // Verificar Open Graph
        if (!setting.hasCompleteOpenGraph()) {
          analysis.incompleteOpenGraph++;
          needsAttention = true;
          issues.push("Open Graph incompleto (Facebook)");
        }

        // Verificar Twitter
        if (!setting.hasCompleteTwitter()) {
          analysis.incompleteTwitter++;
          needsAttention = true;
          issues.push("Twitter Cards incompleto");
        }

        if (needsAttention) {
          analysis.pagesNeedingAttention++;
          pagesWithIssues.push({
            id: setting.id,
            page_type: setting.page_type,
            page_identifier: setting.page_identifier,
            issues
          });
        } else {
          analysis.optimizedPages++;
        }
      });

      // Generar recomendaciones generales basadas en los hallazgos
      if (analysis.missingMetaTitle > 0) {
        analysis.recommendations.push(
          `Prioritario: Tienes ${analysis.missingMetaTitle} página(s) sin título meta. Esto es crítico para el ranking.`
        );
      }
      if (analysis.missingMetaDescription > 0) {
        analysis.recommendations.push(
          `Mejora: ${analysis.missingMetaDescription} página(s) necesitan una descripción meta para mejorar el CTR.`
        );
      }
      if (analysis.incompleteOpenGraph > 0) {
        analysis.recommendations.push(
          `Social Media: Optimiza el Open Graph de ${analysis.incompleteOpenGraph} página(s) para que se vean bien al compartirse.`
        );
      }
      if (analysis.pagesNeedingAttention > 0) {
        analysis.recommendations.push(
          `Consejo: Revisa los detalles específicos de las ${analysis.pagesNeedingAttention} páginas marcadas para llegar al 100%.`
        );
      }

      // Calcular score SEO (0-100) más realista
      const totalPossibleCriterias = analysis.totalPages * 5;
      const totalIssues =
        analysis.missingMetaTitle +
        analysis.missingMetaDescription +
        analysis.missingKeywords +
        analysis.incompleteOpenGraph +
        analysis.incompleteTwitter;

      let score = 100;
      if (totalPossibleCriterias > 0) {
        score = Math.max(0, Math.round(((totalPossibleCriterias - totalIssues) / totalPossibleCriterias) * 100));
      }

      res.json({
        success: true,
        data: {
          score,
          analysis,
          pagesWithIssues,
          lastUpdated: new Date(),
        },
      });
    } catch (error) {
      return sendError(res, error, "Error al generar el análisis SEO", 500, "INTERNAL_SERVER_ERROR");
    }
  }
}

import { Request, Response } from 'express';
import { Setting } from '../models/Setting';
import { sendError } from '../middleware/errorHandler';

export const settingsController = {
    // GET checkout-mode
    async getCheckoutMode(req: Request, res: Response) {
        try {
            const setting = await Setting.findByPk('checkout_mode');
            // Default to 'direct' if not set
            res.json({ mode: setting?.value || 'direct' });
        } catch (error) {
            return sendError(res, error, 'Error al obtener modo de compra');
        }
    },

    // PUT checkout-mode
    async updateCheckoutMode(req: Request, res: Response) {
        try {
            const { mode } = req.body;
            if (!['direct', 'approval'].includes(mode)) {
                return res.status(400).json({ error: 'Modo inválido. Debe ser "direct" o "approval"' });
            }

            // Upsert setting
            const [setting, created] = await Setting.upsert({
                key: 'checkout_mode',
                value: mode
            });

            res.json({
                success: true,
                message: `Modo de compra actualizado a: ${mode}`,
                mode: setting.value
            });
        } catch (error) {
            return sendError(res, error, 'Error al actualizar modo de compra');
        }
    }
};

import { Request, Response } from 'express';
import { Category } from '../../models/Category';
import { Product } from '../../models/Product';
import { Op } from 'sequelize';
import { logger } from '../../config/logger';
import { sendError } from '../../middleware/errorHandler';

export class CategoryController {
    /**
     * GET /api/admin/categories
     * Obtiene todas las categorías con conteo de productos
     */
    static async getAll(req: Request, res: Response) {
        try {
            const categories = await Category.findAll({
                order: [['name', 'ASC']],
                include: [
                    {
                        model: Product,
                        as: 'products',
                        attributes: ['id'],
                    }
                ]
            });

            const categoriesWithCount = categories.map((category: any) => ({
                ...category.toJSON(),
                productCount: category.products?.length || 0
            }));

            res.json(categoriesWithCount);
        } catch (error) {
            logger.error('Error getting categories:', error);
            return sendError(res, error, 'Error al obtener categorías', 500, 'CATEGORIES_FETCH_ERROR');
        }
    }

    /**
     * GET /api/admin/categories/menu
     * Obtiene categorías para el menú (frontend)
     */
    static async getMenu(req: Request, res: Response) {
        try {
            const categories = await Category.findAll({
                where: { appears_in_menu: true },
                order: [['name', 'ASC']],
                attributes: ['id', 'name', 'slug']
            });

            res.json(categories);
        } catch (error) {
            logger.error('Error getting menu categories:', error);
            return sendError(res, error, 'Error al obtener categorías del menú', 500, 'MENU_CATEGORIES_ERROR');
        }
    }

    /**
     * GET /api/admin/categories/:id
     * Obtiene una categoría por ID con sus productos
     */
    static async getById(req: Request, res: Response) {
        try {
            const category = await Category.findByPk(req.params.id, {
                include: [
                    {
                        model: Product,
                        as: 'products',
                        attributes: ['id', 'name', 'price', 'stock'],
                    }
                ]
            });

            if (!category) {
                return res.status(404).json({
                    error: 'Categoría no encontrada',
                    code: 'CATEGORY_NOT_FOUND',
                    timestamp: new Date().toISOString()
                });
            }

            res.json(category);
        } catch (error) {
            logger.error('Error getting category:', error);
            return sendError(res, error, 'Error al obtener categoría', 500, 'CATEGORY_FETCH_ERROR');
        }
    }

    /**
     * POST /api/admin/categories
     * Crea una nueva categoría (genera slug único)
     */
    static async create(req: Request, res: Response) {
        try {
            const { name, appears_in_menu = true } = req.body;

            // Generar slug único
            const baseSlug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
            let slug = baseSlug;
            let counter = 1;

            while (await Category.findOne({ where: { slug } })) {
                slug = `${baseSlug}-${counter}`;
                counter++;
            }

            const category = await Category.create({
                name,
                slug,
                appears_in_menu,
                seo_title: req.body.seo_title ?? null,
                seo_description: req.body.seo_description ?? null,
            });

            res.status(201).json(category);
        } catch (error) {
            logger.error('Error creating category:', error);
            return sendError(res, error, 'Error al crear categoría', 500, 'CATEGORY_CREATE_ERROR');
        }
    }

    /**
     * PUT /api/admin/categories/:id
     * Actualiza una categoría (regenera slug si cambia el nombre)
     */
    static async update(req: Request, res: Response) {
        try {
            const category = await Category.findByPk(req.params.id);

            if (!category) {
                return res.status(404).json({
                    error: 'Categoría no encontrada',
                    code: 'CATEGORY_NOT_FOUND',
                    timestamp: new Date().toISOString()
                });
            }

            const allowedFields = ['name', 'appears_in_menu', 'seo_title', 'seo_description'];
            const updateData: any = {};
            allowedFields.forEach(field => {
                if (req.body[field] !== undefined) {
                    updateData[field] = req.body[field];
                }
            });

            // Si se actualiza el nombre, generar nuevo slug
            if (req.body.name && req.body.name !== category.name) {
                const baseSlug = req.body.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
                let slug = baseSlug;
                let counter = 1;

                while (await Category.findOne({
                    where: {
                        slug,
                        id: { [Op.ne]: category.id }
                    }
                })) {
                    slug = `${baseSlug}-${counter}`;
                    counter++;
                }
                updateData.slug = slug;
            }

            await category.update(updateData);

            res.json(category);
        } catch (error) {
            logger.error('Error updating category:', error);
            return sendError(res, error, 'Error al actualizar categoría', 500, 'CATEGORY_UPDATE_ERROR');
        }
    }

    /**
     * DELETE /api/admin/categories/:id
     * Elimina una categoría (verifica productos asociados)
     */
    static async delete(req: Request, res: Response) {
        try {
            const category = await Category.findByPk(req.params.id);

            if (!category) {
                return res.status(404).json({
                    error: 'Categoría no encontrada',
                    code: 'CATEGORY_NOT_FOUND',
                    timestamp: new Date().toISOString()
                });
            }

            // Verificar si hay productos asociados
            const productCount = await Product.count({ where: { category_id: category.id } });

            if (productCount > 0) {
                return res.status(400).json({
                    error: `No se puede eliminar la categoría porque tiene ${productCount} productos asociados`,
                    code: 'CATEGORY_HAS_PRODUCTS',
                    timestamp: new Date().toISOString()
                });
            }

            await category.destroy();

            res.json({
                message: 'Categoría eliminada correctamente',
                id: category.id
            });
        } catch (error) {
            logger.error('Error deleting category:', error);
            return sendError(res, error, 'Error al eliminar categoría', 500, 'CATEGORY_DELETE_ERROR');
        }
    }
}

import { Request, Response } from 'express';
import { User } from '../../models/User';
import { Op } from 'sequelize';
import { logger } from '../../config/logger';
import { sendError } from '../../middleware/errorHandler';

export class CustomerController {
    /**
     * Get paginated list of customers with filters
     * GET /api/admin/customers?page=1&limit=10&search=&role=&authProvider=&isBlocked=
     */
    static async getCustomers(req: Request, res: Response): Promise<void> {
        try {
            const page = parseInt(req.query.page as string) || 1;
            const limit = parseInt(req.query.limit as string) || 10;
            const search = req.query.search as string || '';
            const role = req.query.role as string;
            const authProvider = req.query.authProvider as string;
            const isBlocked = req.query.isBlocked as string;

            const offset = (page - 1) * limit;

            // Build where clause
            const where: any = {};

            // Search filter
            if (search) {
                where[Op.or] = [
                    { email: { [Op.like]: `%${search}%` } },
                    { first_name: { [Op.like]: `%${search}%` } },
                    { last_name: { [Op.like]: `%${search}%` } }
                ];
            }

            // Role filter
            if (role) {
                where.role = role;
            }

            // Auth provider filter
            if (authProvider) {
                where.auth_provider = { [Op.like]: `%${authProvider}%` };
            }

            // Blocked status filter
            if (isBlocked !== undefined && isBlocked !== '') {
                where.is_blocked = isBlocked === 'true';
            }

            // Get customers with pagination
            const { count, rows: customers } = await User.findAndCountAll({
                where,
                attributes: {
                    exclude: ['password_hash', 'reset_token', 'reset_token_expiry']
                },
                limit,
                offset,
                order: [['createdAt', 'DESC']]
            });

            res.json({
                customers,
                pagination: {
                    page,
                    limit,
                    total: count,
                    totalPages: Math.ceil(count / limit)
                }
            });

        } catch (error) {
            logger.error('❌ Error fetching customers:', error);
            return void sendError(res, error, 'Error fetching customers');
        }
    }

    /**
     * Get customer by ID with details
     * GET /api/admin/customers/:id
     */
    static async getCustomerById(req: Request, res: Response): Promise<void> {
        try {
            const { id } = req.params;

            const customer = await User.findByPk(id, {
                attributes: {
                    exclude: ['password_hash', 'reset_token', 'reset_token_expiry']
                }
            });

            if (!customer) {
                res.status(404).json({ message: 'Customer not found' });
                return;
            }

            res.json({ customer });

        } catch (error) {
            logger.error('❌ Error fetching customer:', error);
            return void sendError(res, error, 'Error fetching customer');
        }
    }

    /**
     * Toggle block/unblock customer
     * PATCH /api/admin/customers/:id/block
     */
    static async toggleBlockCustomer(req: Request, res: Response): Promise<void> {
        try {
            const { id } = req.params;

            const customer = await User.findByPk(id);

            if (!customer) {
                res.status(404).json({ message: 'Customer not found' });
                return;
            }

            // Prevent blocking admins
            if (customer.role === 'admin') {
                res.status(400).json({ message: 'Cannot block admin users' });
                return;
            }

            // Toggle block status
            customer.is_blocked = !customer.is_blocked;
            await customer.save();

            logger.info(`✅ Customer ${customer.email} ${customer.is_blocked ? 'blocked' : 'unblocked'}`);

            res.json({
                message: `Customer ${customer.is_blocked ? 'blocked' : 'unblocked'} successfully`,
                customer: {
                    id: customer.id,
                    email: customer.email,
                    is_blocked: customer.is_blocked
                }
            });

        } catch (error) {
            logger.error('❌ Error toggling customer block:', error);
            return void sendError(res, error, 'Error updating customer');
        }
    }

    /**
     * Get customer statistics
     * GET /api/admin/customers/stats
     */
    static async getCustomerStats(req: Request, res: Response): Promise<void> {
        try {
            // Total customers
            const totalCustomers = await User.count({
                where: { role: 'customer' }
            });

            // Active customers (not blocked)
            const activeCustomers = await User.count({
                where: {
                    role: 'customer',
                    is_blocked: false
                }
            });

            // Blocked customers
            const blockedCustomers = await User.count({
                where: {
                    role: 'customer',
                    is_blocked: true
                }
            });

            // New customers this month
            const firstDayOfMonth = new Date();
            firstDayOfMonth.setDate(1);
            firstDayOfMonth.setHours(0, 0, 0, 0);

            const newThisMonth = await User.count({
                where: {
                    role: 'customer',
                    createdAt: {
                        [Op.gte]: firstDayOfMonth
                    }
                }
            });

            // Customers by auth provider
            const googleCustomers = await User.count({
                where: {
                    role: 'customer',
                    auth_provider: { [Op.like]: '%google%' }
                }
            });

            const localCustomers = await User.count({
                where: {
                    role: 'customer',
                    auth_provider: 'local'
                }
            });

            res.json({
                total: totalCustomers,
                active: activeCustomers,
                blocked: blockedCustomers,
                newThisMonth,
                byProvider: {
                    google: googleCustomers,
                    local: localCustomers
                }
            });

        } catch (error) {
            logger.error('❌ Error fetching customer stats:', error);
            return void sendError(res, error, 'Error fetching statistics');
        }
    }

    /**
     * Get customer orders (placeholder for future implementation)
     * GET /api/admin/customers/:id/orders
     */
    static async getCustomerOrders(req: Request, res: Response): Promise<void> {
        try {
            const { id } = req.params;

            // Check if customer exists
            const customer = await User.findByPk(id);
            if (!customer) {
                res.status(404).json({ message: 'Customer not found' });
                return;
            }

            // TODO: Implement order fetching when Order model is ready
            // For now, return empty array
            res.json({
                orders: [],
                totalOrders: 0,
                totalSpent: 0,
                message: 'Order integration coming soon'
            });

        } catch (error) {
            logger.error('❌ Error fetching customer orders:', error);
            return void sendError(res, error, 'Error fetching orders');
        }
    }
}

import { Request, Response } from 'express';
import Discount from '../../models/Discount';
import { Product } from '../../models/Product';
import { Category } from '../../models/Category';
import { buildPaginationMeta, getSafetyLimit, resolvePagination } from '../../utils/pagination';
import { sendError } from '../../middleware/errorHandler';

const DISCOUNT_EDITABLE_FIELDS = [
    'name',
    'description',
    'discount_type',
    'discount_value',
    'applies_to',
    'category_id',
    'product_id',
    'valid_from',
    'valid_until',
    'is_active'
];

interface DiscountUpdateInput {
    name?: string;
    description?: string;
    discount_type?: 'percentage' | 'fixed';
    discount_value?: number;
    applies_to?: 'all' | 'category' | 'product';
    category_id?: number;
    product_id?: number;
    valid_from?: Date;
    valid_until?: Date;
    is_active?: boolean;
}

function pickDiscountFields(body: unknown): DiscountUpdateInput {
    const data: Record<string, unknown> = {};

    if (body && typeof body === 'object') {
        const source = body as Record<string, unknown>;
        for (const field of DISCOUNT_EDITABLE_FIELDS) {
            if (Object.prototype.hasOwnProperty.call(source, field)) {
                data[field] = source[field];
            }
        }
    }

    return data as DiscountUpdateInput;
}

class DiscountController {
    // --- ADMIN METHODS ---

    /**
     * Get all discounts (Admin)
     */
    async getAllDiscounts(req: Request, res: Response) {
        try {
            const { page, limit, offset, paginated } = resolvePagination(req.query);

            if (paginated) {
                const [{ rows, count }, active] = await Promise.all([
                    Discount.findAndCountAll({
                        order: [['created_at', 'DESC']],
                        limit,
                        offset
                    }),
                    Discount.count({ where: { is_active: true } })
                ]);
                return res.status(200).json({
                    success: true,
                    data: rows,
                    pagination: buildPaginationMeta(page, limit, count),
                    summary: { active, total: count }
                });
            }

            const discounts = await Discount.findAll({
                order: [['created_at', 'DESC']],
                limit: getSafetyLimit(limit)
            });
            return res.status(200).json({ success: true, data: discounts });
        } catch (error) {
            return sendError(res, error, 'Error al obtener descuentos');
        }
    }

    /**
     * Create discount (Admin)
     */
    async createDiscount(req: Request, res: Response) {
        try {
            const {
                name,
                description,
                discount_type,
                discount_value,
                applies_to,
                category_id,
                product_id,
                valid_from,
                valid_until,
                is_active
            } = req.body;

            const discount = await Discount.create({
                name,
                description,
                discount_type,
                discount_value,
                applies_to,
                category_id: category_id || null,
                product_id: product_id || null,
                valid_from,
                valid_until,
                is_active: is_active ?? true
            });

            return res.status(201).json({ success: true, message: 'Descuento creado', data: discount });
        } catch (error) {
            return sendError(res, error, 'Error al crear descuento');
        }
    }

    /**
     * Update discount (Admin)
     */
    async updateDiscount(req: Request, res: Response) {
        try {
            const { id } = req.params;
            const discount = await Discount.findByPk(id);

            if (!discount) {
                return res.status(404).json({ success: false, message: 'Descuento no encontrado' });
            }

            await discount.update(pickDiscountFields(req.body));
            return res.status(200).json({ success: true, message: 'Descuento actualizado', data: discount });
        } catch (error) {
            return sendError(res, error, 'Error al actualizar descuento');
        }
    }

    /**
     * Delete discount (Admin)
     */
    async deleteDiscount(req: Request, res: Response) {
        try {
            const { id } = req.params;
            const discount = await Discount.findByPk(id);

            if (!discount) {
                return res.status(404).json({ success: false, message: 'Descuento no encontrado' });
            }

            await discount.destroy();
            return res.status(200).json({ success: true, message: 'Descuento eliminado' });
        } catch (error) {
            return sendError(res, error, 'Error al eliminar descuento');
        }
    }
}

export const discountController = new DiscountController();

import { Request, Response } from 'express';
import { Order } from '../../models/Order';
import multer from 'multer';
import path from 'path';
import fs from 'fs';
import { EmailService } from '../../services/EmailService';
import { logger } from '../../config/logger';
import { sendError } from '../../middleware/errorHandler';

// Configurar multer para subir comprobantes (facturas/boletas)
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        const uploadDir = path.join(__dirname, '../../../uploads/invoices');
        if (!fs.existsSync(uploadDir)) {
            fs.mkdirSync(uploadDir, { recursive: true });
        }
        cb(null, uploadDir);
    },
    filename: (req, file, cb) => {
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, 'invoice-' + uniqueSuffix + path.extname(file.originalname));
    }
});

const fileFilter = (req: any, file: Express.Multer.File, cb: multer.FileFilterCallback) => {
    // Solo aceptar archivos PDF
    if (file.mimetype === 'application/pdf') {
        cb(null, true);
    } else {
        cb(new Error('Solo se permiten archivos PDF'));
    }
};

export const uploadInvoice = multer({
    storage: storage,
    limits: { fileSize: 10 * 1024 * 1024 }, // 10MB max
    fileFilter: fileFilter
});

// Upload invoice/boleta generada externamente
export const uploadInvoiceFile = async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        const { invoice_number } = req.body;

        const order = await Order.findByPk(id);
        if (!order) {
            return res.status(404).json({ error: 'Pedido no encontrado' });
        }

        if (order.payment_status !== 'verified') {
            return res.status(400).json({ error: 'El pago debe estar verificado primero' });
        }

        if (!req.file) {
            return res.status(400).json({ error: 'Debe subir un archivo PDF' });
        }

        if (!invoice_number) {
            return res.status(400).json({ error: 'Debe proporcionar el número de comprobante' });
        }

        // Update order with invoice info
        order.invoice_number = invoice_number;
        order.invoice_file = req.file.filename;
        await order.save();

        // Enviar factura/boleta al cliente por email
        try {
            const emailService = new EmailService();
            await emailService.sendInvoiceToClient(order, req.file.filename);
            logger.info(`✅ Comprobante enviado por email al cliente para pedido #${order.id}`);
        } catch (emailError) {
            logger.error('⚠️ Error enviando comprobante por email:', emailError);
            // No fallar la operación si el email falla
        }

        res.json({
            success: true,
            message: 'Comprobante cargado exitosamente',
            invoice_file: req.file.filename,
            invoice_number
        });
    } catch (error) {
        logger.error('Error uploading invoice:', error);
        return sendError(res, error, 'Error al cargar comprobante');
    }
};

import { Request, Response } from 'express';
import { Product } from '../../models/Product';
import { Brand } from '../../models/Brand';
import { Category } from '../../models/Category';
import { Image } from '../../models/Image';
import { PeruanaInformaticaService } from '../../services/PeruanaInformaticaService';
import { logger } from '../../config/logger';
import { sendError } from '../../middleware/errorHandler';

export class ProductErpController {
    async erpLookup(req: Request, res: Response) {
        try {
            const { code } = req.params;

            // 1. Buscar en BD local primero
            const existingProduct = await Product.findOne({
                where: { codigo_interno: code },
                include: [
                    { model: Brand, as: 'productBrand', attributes: ['id', 'name'] },
                    { model: Category, as: 'productCategory', attributes: ['id', 'name'] },
                    { model: Image, as: 'images', attributes: ['cod_galeria', 'imagen'] }
                ]
            });

            if (existingProduct) {
                return res.json({
                    found: true,
                    source: 'db',
                    message: 'El producto ya existe en la base de datos',
                    product: {
                        ...existingProduct.toJSON(),
                        id: existingProduct.cod_producto
                    }
                });
            }

            // 2. Buscar en API del sistema de ventas (ERP real)
            try {
                logger.info(`Buscando producto ${code} en API de ventas...`);
                const erpResult = await PeruanaInformaticaService.consultarArticulo(String(code));
                logger.info('Respuesta API:', JSON.stringify(erpResult, null, 2));

                let articulo = null;

                if (erpResult) {
                    if (erpResult.success && erpResult.data) {
                        articulo = erpResult.data;
                    } else if (!erpResult.success && erpResult.message) {
                        return res.json({
                            found: false,
                            message: erpResult.message || 'Error al consultar el sistema de ventas'
                        });
                    }
                }

                if (articulo) {
                    return res.json({
                        found: true,
                        source: 'erp',
                        message: 'Producto encontrado en sistema de ventas',
                        product: {
                            codigo: articulo.cod_articulo || articulo.id || code,
                            nombre: articulo.nombre || articulo.descripcion || 'Sin nombre',
                            precio: parseFloat(articulo.pre_web) || parseFloat(articulo.pre_cli) || parseFloat(articulo.pre_cot) || 0,
                            stock: parseInt(articulo.stock) || 0,
                            marca: articulo.marca || null,
                            categoria: articulo.categoria || null,
                            pre_cot: parseFloat(articulo.pre_cot) || 0,
                            pre_cli: parseFloat(articulo.pre_cli) || 0,
                            pre_web: parseFloat(articulo.pre_web) || 0,
                            pre_dis: parseFloat(articulo.pre_dis) || 0
                        }
                    });
                } else {
                    return res.json({
                        found: false,
                        message: 'Producto no encontrado en el sistema de ventas'
                    });
                }
            } catch (apiError: any) {
                logger.error('Error consultando API de ventas:', apiError.message);

                if (apiError.message?.includes('401') || apiError.message?.includes('Unauthorized') || apiError.message?.includes('autorizado')) {
                    return res.json({
                        found: false,
                        message: 'Token de API expirado. Contacte al administrador para renovar el token.'
                    });
                }

                return res.json({
                    found: false,
                    message: 'Error al consultar sistema de ventas: ' + (apiError.message || 'Error desconocido')
                });
            }

        } catch (error) {
            logger.error('Error in ERP lookup:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }
}

export const productErpController = new ProductErpController();

import { Request, Response } from 'express';
import { sequelize } from '../../database/connection';
import { PeruanaInformaticaService } from '../../services/PeruanaInformaticaService';
import { geminiService } from '../../services/GeminiService';
import os from 'os';

interface ServiceHealth {
    status: string;
    latency: number;
    message?: string;
}

interface SystemHealthData {
    database: ServiceHealth;
    externalApi: ServiceHealth;
    geminiApi: ServiceHealth;
    googleAuth: { status: string; message?: string };
    system: {
        uptime: number;
        memoryUsage: NodeJS.MemoryUsage;
        freeMemory: number;
        totalMemory: number;
        loadAvg: number[];
    };
    timestamp: string;
}

interface ServiceCheckResult {
    type: 'database' | 'externalApi' | 'geminiApi';
    status: string;
    latency: number;
    message?: string;
}

export const getSystemHealth = async (req: Request, res: Response) => {
    const healthData: SystemHealthData = {
        database: { status: 'unknown', latency: 0 },
        externalApi: { status: 'unknown', latency: 0 },
        geminiApi: { status: 'unknown', latency: 0 },
        googleAuth: { status: 'unknown', message: 'Not configured' },
        system: {
            uptime: process.uptime(),
            memoryUsage: process.memoryUsage(),
            freeMemory: os.freemem(),
            totalMemory: os.totalmem(),
            loadAvg: os.loadavg()
        },
        timestamp: new Date().toISOString()
    };

    const start = Date.now();

    // Probamos todos los servicios en paralelo para mejorar el tiempo de respuesta
    const results = await Promise.allSettled([
        // 1. Base de Datos
        (async (): Promise<ServiceCheckResult> => {
            const dbStart = Date.now();
            try {
                await sequelize.authenticate();
                return { type: 'database', status: 'ok', latency: Date.now() - dbStart };
            } catch {
                return { type: 'database', status: 'error', message: 'No disponible', latency: Date.now() - dbStart };
            }
        })(),

        // 2. API Externa
        (async (): Promise<ServiceCheckResult> => {
            const apiHealth = await PeruanaInformaticaService.checkHealth();
            return { type: 'externalApi', ...apiHealth };
        })(),

        // 3. Gemini API
        (async (): Promise<ServiceCheckResult> => {
            const geminiStart = Date.now();
            try {
                if (process.env.GEMINI_API_KEY) {
                    const isReady = await geminiService.verifyApiKey();
                    return {
                        type: 'geminiApi',
                        status: isReady ? 'ok' : 'error',
                        message: isReady ? undefined : 'API Key no funcional',
                        latency: Date.now() - geminiStart
                    };
                }
                return { type: 'geminiApi', status: 'error', message: 'Falta GEMINI_API_KEY', latency: 0 };
            } catch {
                return { type: 'geminiApi', status: 'error', message: 'No disponible', latency: Date.now() - geminiStart };
            }
        })()
    ]);

    // Procesar resultados
    results.forEach((result) => {
        if (result.status === 'fulfilled') {
            const val = result.value;
            if (val.type === 'database') {
                healthData.database.status = val.status;
                healthData.database.latency = val.latency;
                healthData.database.message = val.message;
            } else if (val.type === 'externalApi') {
                healthData.externalApi.status = val.status;
                healthData.externalApi.latency = val.latency;
                healthData.externalApi.message = val.message;
            } else if (val.type === 'geminiApi') {
                healthData.geminiApi.status = val.status;
                healthData.geminiApi.latency = val.latency;
                healthData.geminiApi.message = val.message;
            }
        }
    });

    // Google Auth Check (Síncrono)
    if (process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET) {
        healthData.googleAuth.status = 'ok';
        healthData.googleAuth.message = 'Configurado';
    } else {
        healthData.googleAuth.status = 'error';
        healthData.googleAuth.message = 'Faltan credenciales en .env';
    }

    res.json(healthData);
};

import { Request, Response } from 'express';
import { Order } from '../models/Order';
import { OrderItem } from '../models/OrderItem';
import { Product } from '../models/Product';
import { Image } from '../models/Image';
import { Review } from '../models/Review';
import { User } from '../models/User';
import { Op } from 'sequelize';
import { logger } from '../config/logger';
import { sendError } from '../middleware/errorHandler';

export class AnalyticsController {

    /**
     * Get sales overview - revenue over time
     */
    async getSalesOverview(req: Request, res: Response) {
        try {
            const { period = '30d' } = req.query;

            // Calculate date range
            const now = new Date();
            const startDate = new Date();

            switch (period) {
                case '7d':
                    startDate.setDate(now.getDate() - 7);
                    break;
                case '30d':
                    startDate.setDate(now.getDate() - 30);
                    break;
                case '90d':
                    startDate.setDate(now.getDate() - 90);
                    break;
                case '1y':
                    startDate.setFullYear(now.getFullYear() - 1);
                    break;
                default:
                    startDate.setDate(now.getDate() - 30);
            }

            // Get daily sales
            const dailySales = await Order.findAll({
                attributes: [
                    [Order.sequelize!.fn('DATE', Order.sequelize!.col('createdAt')), 'date'],
                    [Order.sequelize!.fn('COUNT', Order.sequelize!.col('id')), 'orders'],
                    [Order.sequelize!.fn('SUM', Order.sequelize!.col('total_amount')), 'revenue']
                ],
                where: {
                    createdAt: {
                        [Op.gte]: startDate
                    },
                    payment_status: 'verified'
                },
                group: [Order.sequelize!.fn('DATE', Order.sequelize!.col('createdAt'))],
                order: [[Order.sequelize!.fn('DATE', Order.sequelize!.col('createdAt')), 'ASC']],
                raw: true
            });

            return res.json({
                success: true,
                data: dailySales
            });
        } catch (error) {
            logger.error('Error fetching sales overview:', error);
            return sendError(res, error, 'Error al obtener resumen de ventas');
        }
    }

    /**
     * Get key performance indicators (KPIs)
     */
    async getKPIs(req: Request, res: Response) {
        try {
            // Total revenue (all time)
            const totalRevenue = await Order.sum('total_amount', {
                where: { payment_status: 'verified' }
            }) || 0;

            // Total orders
            const totalOrders = await Order.count({
                where: { payment_status: 'verified' }
            });

            // Average order value
            const avgOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;

            // Revenue this month
            const startOfMonth = new Date();
            startOfMonth.setDate(1);
            startOfMonth.setHours(0, 0, 0, 0);

            const monthRevenue = await Order.sum('total_amount', {
                where: {
                    payment_status: 'verified',
                    createdAt: {
                        [Op.gte]: startOfMonth
                    }
                }
            }) || 0;

            // Orders this month
            const monthOrders = await Order.count({
                where: {
                    payment_status: 'verified',
                    createdAt: {
                        [Op.gte]: startOfMonth
                    }
                }
            });

            // Pending orders (require attention)
            const pendingOrders = await Order.count({
                where: { payment_status: 'pending' }
            });

            // Total customers (unique users)
            const totalCustomers = await Order.count({
                distinct: true,
                col: 'customer_email',
                where: { payment_status: 'verified' }
            });

            // New customers this month
            const newCustomersMonth = await Order.count({
                distinct: true,
                col: 'customer_email',
                where: {
                    payment_status: 'verified',
                    createdAt: {
                        [Op.gte]: startOfMonth
                    }
                }
            });

            return res.json({
                success: true,
                data: {
                    totalRevenue: Number(totalRevenue).toFixed(2),
                    totalOrders,
                    avgOrderValue: Number(avgOrderValue).toFixed(2),
                    monthRevenue: Number(monthRevenue).toFixed(2),
                    monthOrders,
                    pendingOrders,
                    totalCustomers,
                    newCustomersMonth
                }
            });
        } catch (error) {
            logger.error('Error fetching KPIs:', error);
            return sendError(res, error, 'Error al obtener KPIs');
        }
    }

    /**
     * Get top selling products
     */
    async getTopProducts(req: Request, res: Response) {
        try {
            const { limit = 10 } = req.query;

            // 1. Get aggregated stats from OrderItems
            const topSellingItems = await OrderItem.findAll({
                attributes: [
                    'product_id',
                    [OrderItem.sequelize!.fn('SUM', OrderItem.sequelize!.col('quantity')), 'total_sold'],
                    [OrderItem.sequelize!.fn('SUM', OrderItem.sequelize!.literal('quantity * price')), 'total_revenue']
                ],
                group: ['product_id'],
                order: [[OrderItem.sequelize!.fn('SUM', OrderItem.sequelize!.col('quantity')), 'DESC']],
                limit: Number(limit)
            });

            // 2. Get product details for these items
            const productIds = topSellingItems.map(item => item.product_id);

            const products = await Product.findAll({
                where: {
                    cod_producto: {
                        [Op.in]: productIds
                    }
                },
                attributes: ['cod_producto', 'codigo_interno', 'name', 'slug', 'price', 'stock'],
                include: [{
                    model: Image,
                    as: 'images',
                    attributes: ['imagen'],
                    limit: 1
                }]
            });

            // 3. Merge data
            const results = topSellingItems.map(item => {
                const product = products.find(p => p.cod_producto === item.product_id);
                const itemData = item.get({ plain: true });
                return {
                    ...itemData,
                    product: product ? {
                        ...product.get({ plain: true }),
                        image: product.images?.[0]?.imagen || null // Simplify image access for frontend
                    } : null
                };
            });

            return res.json({
                success: true,
                data: results
            });
        } catch (error) {
            logger.error('Error fetching top products:', error);
            return sendError(res, error, 'Error al obtener productos más vendidos');
        }
    }

    /**
     * Get sales by payment method
     */
    async getSalesByPaymentMethod(req: Request, res: Response) {
        try {
            const salesByMethod = await Order.findAll({
                attributes: [
                    'payment_method',
                    [Order.sequelize!.fn('COUNT', Order.sequelize!.col('id')), 'count'],
                    [Order.sequelize!.fn('SUM', Order.sequelize!.col('total_amount')), 'revenue']
                ],
                where: {
                    payment_status: 'verified',
                    payment_method: { [Op.not]: null }
                },
                group: ['payment_method'],
                raw: true
            });

            return res.json({
                success: true,
                data: salesByMethod
            });
        } catch (error) {
            logger.error('Error fetching sales by payment method:', error);
            return sendError(res, error, 'Error al obtener ventas por método de pago');
        }
    }

    /**
     * Get recent orders
     */
    async getRecentOrders(req: Request, res: Response) {
        try {
            const { limit = 10 } = req.query;

            const recentOrders = await Order.findAll({
                attributes: ['id', 'customer_name', 'customer_email', 'total_amount', 'payment_status', 'status', 'createdAt'],
                order: [['createdAt', 'DESC']],
                limit: Number(limit)
            });

            return res.json({
                success: true,
                data: recentOrders
            });
        } catch (error) {
            logger.error('Error fetching recent orders:', error);
            return sendError(res, error, 'Error al obtener pedidos recientes');
        }
    }

    /**
     * Get conversion metrics
     */
    async getConversionMetrics(req: Request, res: Response) {
        try {
            // Total products viewed (approximate using reviews as proxy)
            const totalReviews = await Review.count();

            // Total orders
            const totalOrders = await Order.count();

            // Verified orders
            const verifiedOrders = await Order.count({
                where: { payment_status: 'verified' }
            });

            // Conversion rate (orders / product views) - simplified
            const conversionRate = totalReviews > 0 ? (verifiedOrders / totalReviews) * 100 : 0;

            // Payment verification rate
            const verificationRate = totalOrders > 0 ? (verifiedOrders / totalOrders) * 100 : 0;

            return res.json({
                success: true,
                data: {
                    totalOrders,
                    verifiedOrders,
                    conversionRate: conversionRate.toFixed(2),
                    verificationRate: verificationRate.toFixed(2)
                }
            });
        } catch (error) {
            logger.error('Error fetchingconversion metrics:', error);
            return sendError(res, error, 'Error al obtener métricas de conversión');
        }
    }
}

