import { Request, Response } from "express";
import { Op } from "sequelize";
import { BlogPost } from "../../models/BlogPost";
import { sendError } from "../../middleware/errorHandler";

export class BlogPublicController {
  static async getPublishedPosts(req: Request, res: Response) {
    try {
      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 10;
      const category = req.query.category as string;
      const tag = req.query.tag as string;
      const search = req.query.search as string;

      const offset = (page - 1) * limit;
      const whereClause: any = {
        status: "published",
        // Todos los posts publicados se muestran (sin filtro de fecha/hora)
      };

      // Filtros
      if (category) {
        whereClause.categories = {
          [Op.like]: `%${category}%`,
        };
      }

      if (tag) {
        whereClause.tags = {
          [Op.like]: `%${tag}%`,
        };
      }

      if (search) {
        whereClause[Op.or] = [
          { title: { [Op.like]: `%${search}%` } },
          { excerpt: { [Op.like]: `%${search}%` } },
          { content: { [Op.like]: `%${search}%` } },
          { tags: { [Op.like]: `%${search}%` } },
        ];
      }

      const { count, rows } = await BlogPost.findAndCountAll({
        where: whereClause,
        limit,
        offset,
        order: [
          ["is_featured", "DESC"],
          ["published_at", "DESC"],
        ],
        attributes: {
          exclude: ["ai_prompt"], // No exponer prompts en público
        },
      });

      const totalPages = Math.ceil(count / limit);

      res.json({
        success: true,
        data: rows,
        pagination: {
          currentPage: page,
          totalPages,
          totalItems: count,
          itemsPerPage: limit,
          hasNextPage: page < totalPages,
          hasPrevPage: page > 1,
        },
      });
    } catch (error) {
      return sendError(res, error, "Error al obtener los posts del blog", 500, "INTERNAL_SERVER_ERROR");
    }
  }

  // Obtener post por slug (frontend público)
  static async getPostBySlug(req: Request, res: Response) {
    try {
      const { slug } = req.params;

      const post = await BlogPost.findOne({
        where: {
          slug,
          status: "published",
          // Sin filtro de fecha - todos los posts publicados son visibles
        },
        attributes: {
          exclude: ["ai_prompt"], // No exponer prompts en público
        },
      });

      if (!post) {
        return res.status(404).json({
          error: "Post no encontrado",
          message: "El post solicitado no existe o no está publicado",
          code: "POST_NOT_FOUND",
        });
      }

      // Incrementar vistas
      await post.incrementViews();

      res.json({
        success: true,
        data: post,
      });
    } catch (error) {
      return sendError(res, error, "Error al obtener el post", 500, "INTERNAL_SERVER_ERROR");
    }
  }

  // Incrementar likes de un post
  static async likePost(req: Request, res: Response) {
    try {
      const { id } = req.params;

      const post = await BlogPost.findByPk(id);

      if (!post || post.status !== "published") {
        return res.status(404).json({
          error: "Post no encontrado",
          message: "El post solicitado no existe o no está publicado",
          code: "POST_NOT_FOUND",
        });
      }

      await post.incrementLikes();

      res.json({
        success: true,
        message: "Like registrado exitosamente",
        data: { likes: post.likes + 1 },
      });
    } catch (error) {
      return sendError(res, error, "Error al procesar el like", 500, "INTERNAL_SERVER_ERROR");
    }
  }
}

import { Request, Response } from 'express';
import { Cart } from '../models/Cart';
import { CartItem } from '../models/CartItem';
import { Product } from '../models/Product';
import { sequelize } from '../database/connection';
import { sendError } from '../middleware/errorHandler';

export const cartController = {
    // Get Cart (Create if not exists)
    async getCart(req: Request, res: Response) {
        try {
            // @ts-ignore
            const userId = req.user?.id;
            if (!userId) return res.status(401).json({ error: 'Unauthorized' });

            const [cart] = await Cart.findOrCreate({
                where: { user_id: userId, status: 'active' },
                defaults: { user_id: userId, status: 'active' }
            });

            const items = await CartItem.findAll({
                where: { cart_id: cart.id },
                include: [{ model: Product, as: 'product' }]
            });

            res.json({ cart, items });
        } catch (error) {
            return sendError(res, error, 'Error getting cart');
        }
    },

    // Sync Cart (Merge Local with Server)
    async syncCart(req: Request, res: Response) {
        const t = await sequelize.transaction();
        try {
            // @ts-ignore
            const userId = req.user?.id;
            const localItems = req.body.items || []; // Expected: [{ productId, quantity }]

            const [cart] = await Cart.findOrCreate({
                where: { user_id: userId, status: 'active' },
                defaults: { user_id: userId, status: 'active' },
                transaction: t
            });

            // Current server items
            const serverItems = await CartItem.findAll({ where: { cart_id: cart.id }, transaction: t });

            // Merge Strategy: 
            // 1. If product exists in both, use MAX(quantity) or Local (last wins) - Let's use local quantity as it's the latest user intent
            // 2. If product only in local, add to server.
            // 3. If product only in server, KEEP it (persistence).

            for (const localItem of localItems) {
                const existing = serverItems.find(i => i.product_id === localItem.id); // frontend sends 'id' as product id

                if (existing) {
                    // Update quantity if different
                    if (existing.quantity !== localItem.quantity) {
                        await existing.update({ quantity: localItem.quantity }, { transaction: t });
                    }
                } else {
                    // Create new
                    await CartItem.create({
                        cart_id: cart.id,
                        product_id: localItem.id,
                        quantity: localItem.quantity
                    }, { transaction: t });
                }
            }

            await t.commit();

            // Return updated full cart
            const updatedItems = await CartItem.findAll({
                where: { cart_id: cart.id },
                include: [{ model: Product, as: 'product' }]
            });

            res.json({ cart, items: updatedItems });

        } catch (error) {
            await t.rollback();
            return sendError(res, error, 'Error syncing cart');
        }
    },

    // Update Item (Add/Modify)
    async updateItem(req: Request, res: Response) {
        try {
            // @ts-ignore
            const userId = req.user?.id;
            const { productId, quantity } = req.body;

            const [cart] = await Cart.findOrCreate({
                where: { user_id: userId, status: 'active' },
                defaults: { user_id: userId, status: 'active' }
            });

            const [item, created] = await CartItem.findOrCreate({
                where: { cart_id: cart.id, product_id: productId },
                defaults: { cart_id: cart.id, product_id: productId, quantity }
            });

            if (!created) {
                if (quantity > 0) {
                    await item.update({ quantity });
                } else {
                    await item.destroy();
                }
            }

            res.json({ success: true, item });
        } catch (error) {
            return sendError(res, error, 'Error updating item');
        }
    },

    // Remove Item
    async removeItem(req: Request, res: Response) {
        try {
            // @ts-ignore
            const userId = req.user?.id;
            const { productId } = req.params;

            const cart = await Cart.findOne({ where: { user_id: userId, status: 'active' } });
            if (cart) {
                await CartItem.destroy({ where: { cart_id: cart.id, product_id: productId } });
            }

            res.json({ success: true });
        } catch (error) {
            return sendError(res, error, 'Error removing item');
        }
    }
};

import { Request, Response } from 'express';
import { Page } from '../models/Page';
import { Op } from 'sequelize';
import { logger } from '../config/logger';
import { sendError } from '../middleware/errorHandler';

export class PageController {

    // Admin: Get all pages
    async getAllPages(req: Request, res: Response) {
        try {
            const page = parseInt(req.query.page as string) || 1;
            const limit = parseInt(req.query.limit as string) || 10;
            const offset = (page - 1) * limit;
            const search = req.query.search as string;

            const whereClause: any = {};
            if (search) {
                whereClause.title = { [Op.like]: `%${search}%` };
            }

            const { count, rows } = await Page.findAndCountAll({
                where: whereClause,
                limit,
                offset,
                order: [['created_at', 'DESC']],
            });

            return res.json({
                success: true,
                data: rows,
                pagination: {
                    total: count,
                    currentPage: page,
                    totalPages: Math.ceil(count / limit),
                },
            });
        } catch (error) {
            logger.error('Error fetching pages:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }

    // Public: Get page by slug
    async getPageBySlug(req: Request, res: Response) {
        try {
            const { slug } = req.params;
            const page = await Page.findOne({
                where: { slug, is_published: true },
                attributes: ['title', 'content', 'meta_title', 'meta_description', 'updated_at']
            });

            if (!page) {
                return res.status(404).json({ error: 'Página no encontrada' });
            }

            return res.json({ success: true, data: page });
        } catch (error) {
            logger.error('Error fetching page by slug:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }

    // Admin: Get page by ID
    async getPageById(req: Request, res: Response) {
        try {
            const { id } = req.params;
            const page = await Page.findByPk(id);

            if (!page) {
                return res.status(404).json({ error: 'Página no encontrada' });
            }

            return res.json({ success: true, data: page });
        } catch (error) {
            logger.error('Error getting page:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }

    // Admin: Create page
    async createPage(req: Request, res: Response) {
        try {
            const { title, slug, content, is_published, meta_title, meta_description } = req.body;

            // Check for duplicate slug
            const existingPage = await Page.findOne({ where: { slug } });
            if (existingPage) {
                return res.status(400).json({ error: 'Ya existe una página con este enlace (slug)' });
            }

            const newPage = await Page.create({
                title,
                slug,
                content,
                is_published,
                meta_title,
                meta_description,
            });

            return res.status(201).json({ success: true, data: newPage });
        } catch (error) {
            logger.error('Error creating page:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }

    // Admin: Update page
    async updatePage(req: Request, res: Response) {
        try {
            const { id } = req.params;
            const { title, slug, content, is_published, meta_title, meta_description } = req.body;

            const page = await Page.findByPk(id);
            if (!page) {
                return res.status(404).json({ error: 'Página no encontrada' });
            }

            // Check slug uniqueness if changed
            if (slug && slug !== page.slug) {
                const existingPage = await Page.findOne({ where: { slug } });
                if (existingPage) {
                    return res.status(400).json({ error: 'Ya existe una página con este enlace' });
                }
            }

            await page.update({
                title,
                slug,
                content,
                is_published,
                meta_title,
                meta_description,
            });

            return res.json({ success: true, data: page });
        } catch (error) {
            logger.error('Error updating page:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }

    // Admin: Delete page
    async deletePage(req: Request, res: Response) {
        try {
            const { id } = req.params;
            const page = await Page.findByPk(id);

            if (!page) {
                return res.status(404).json({ error: 'Página no encontrada' });
            }

            await page.destroy();
            return res.json({ success: true, message: 'Página eliminada correctamente' });
        } catch (error) {
            logger.error('Error deleting page:', error);
            return sendError(res, error, 'Error interno del servidor');
        }
    }
}

