import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { requireJwtSecret } from '../config/env';

// Extender Request interface localmente
interface AuthRequest extends Request {
    user?: {
        id: number;
        email: string;
        role?: string;
    };
}

const JWT_SECRET = requireJwtSecret();

export const authenticateToken = (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
        return res.status(401).json({ error: 'Acceso denegado. Token no proporcionado.' });
    }

    jwt.verify(token, JWT_SECRET, (err: any, user: any) => {
        if (err) {
            return res.status(403).json({ error: 'Token inválido o expirado' });
        }
        (req as AuthRequest).user = user;
        next();
    });
};

export const requireAdmin = (req: Request, res: Response, next: NextFunction) => {
    const userRole = (req as AuthRequest).user?.role;
    // Allow admin, super-admin, etc.
    if (userRole && ['admin', 'super-admin'].includes(userRole)) {
        next();
    } else {
        return res.status(403).json({ error: 'Role unauthorized' });
    }
};

import { Request, Response, NextFunction } from 'express';
import { getCache, setCache, isRedisReady } from '../config/redis';
import { logger } from '../config/logger';

/**
 * Cache middleware factory
 * @param keyPrefix - Prefix for cache key
 * @param ttl - Time to live in seconds (default: 5 minutes)
 */
export function cacheMiddleware(keyPrefix: string, ttl: number = 300) {
    return async (req: Request, res: Response, next: NextFunction) => {
        // Skip cache if Redis is not available
        if (!isRedisReady()) {
            return next();
        }

        try {
            // Generate cache key from request
            const cacheKey = generateCacheKey(keyPrefix, req);

            // Try to get from cache
            const cached = await getCache(cacheKey);

            if (cached) {
                logger.info(`✅ Cache HIT: ${cacheKey}`);
                return res.json(cached);
            }

            logger.info(`❌ Cache MISS: ${cacheKey}`);

            // Store original json method
            const originalJson = res.json.bind(res);

            // Override json method to cache the response
            res.json = function (data: any) {
                // Cache the response
                setCache(cacheKey, data, ttl).catch((error) => {
                    logger.warn('Failed to cache response:', error);
                });

                // Call original json method
                return originalJson(data);
            };

            next();
        } catch (error) {
            logger.error('Cache middleware error:', error);
            next();
        }
    };
}

/**
 * Generate cache key from request
 */
function generateCacheKey(prefix: string, req: Request): string {
    const path = req.path;
    const query = JSON.stringify(req.query);
    return `${prefix}:${path}:${query}`;
}

/**
 * Cache only on successful responses
 */
export function cacheSuccessMiddleware(keyPrefix: string, ttl: number = 300) {
    return async (req: Request, res: Response, next: NextFunction) => {
        if (!isRedisReady()) {
            return next();
        }

        const cacheKey = generateCacheKey(keyPrefix, req);

        // Check cache
        const cached = await getCache(cacheKey);
        if (cached) {
            logger.info(`✅ Cache HIT: ${cacheKey}`);
            return res.json(cached);
        }

        // Store original methods
        const originalJson = res.json.bind(res);
        const originalStatus = res.status.bind(res);
        let statusCode = 200;

        // Track status code
        res.status = function (code: number) {
            statusCode = code;
            return originalStatus(code);
        };

        // Override json to cache only on success
        res.json = function (data: any) {
            if (statusCode >= 200 && statusCode < 300) {
                setCache(cacheKey, data, ttl).catch(() => { });
            }
            return originalJson(data);
        };

        next();
    };
}

import { Router } from 'express';
import { body, validationResult } from 'express-validator';
import { Request, Response, NextFunction } from 'express';

/**
 * Middleware to handle validation errors
 */
export const handleValidationErrors = (req: Request, res: Response, next: NextFunction) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            success: false,
            errors: errors.array()
        });
    }
    next();
};

