}

interface SeoSettingsCreationAttributes
  extends Optional<
    SeoSettingsAttributes,
    | "id"
    | "page_identifier"
    | "meta_title"
    | "meta_description"
    | "meta_keywords"
    | "og_title"
    | "og_description"
