  > {}

class SeoSettings
  extends Model<SeoSettingsAttributes, SeoSettingsCreationAttributes>
  implements SeoSettingsAttributes
{
  public id!: number;
  public page_type!: string;
  public page_identifier?: string;
  public meta_title?: string;
  public meta_description?: string;
  public meta_keywords?: string;
  public og_title?: string;
  public og_description?: string;
  public og_image?: string;
  public twitter_title?: string;
  public twitter_description?: string;
  public twitter_image?: string;
  public canonical_url?: string;
  public robots!: string;
  public schema_markup?: string;
  public custom_head?: string;
  public priority!: number;
  public change_frequency!: "always" | "hourly" | "daily" | "weekly" | "monthly" | "yearly" | "never";
  public is_active!: boolean;
  public readonly createdAt!: Date;
  public readonly updatedAt!: Date;

  // Método para obtener el título efectivo
  public getEffectiveTitle(): string {
    return this.meta_title || "Peruana de Informática";
  }

  // Método para obtener la descripción efectiva
  public getEffectiveDescription(): string {
    return this.meta_description || "Tu tienda de confianza para equipos informáticos";
  }

  // Método para obtener keywords como array
  public getKeywordsArray(): string[] {
    if (!this.meta_keywords) return [];
    return this.meta_keywords.split(",").map((k) => k.trim()).filter(Boolean);
  }

  // Método para verificar si tiene configuración Open Graph completa
  public hasCompleteOpenGraph(): boolean {
    return !!(this.og_title && this.og_description);
  }

  // Método para verificar si tiene configuración Twitter completa
  public hasCompleteTwitter(): boolean {
    return !!(this.twitter_title && this.twitter_description);
  }

  // Método para generar JSON-LD schema básico
  public generateBasicSchema(siteUrl: string = "https://peruanainformatica.com"): object | null {
    if (this.schema_markup) {
      try {
        return JSON.parse(this.schema_markup);
      } catch (error) {
        logger.error("Error parsing schema markup:", error);
        return null;
      }
    }

    // Schema básico para la organización
    if (this.page_type === "global" || this.page_type === "home") {
      return {
        "@context": "https://schema.org",
        "@type": "Organization",
        name: "Peruana de Informática",
        url: siteUrl,
        description: this.getEffectiveDescription(),
        sameAs: [
          "https://facebook.com/peruanainformatica",
          "https://twitter.com/peruanainformatica",
        ],
      };
    }

    return null;
  }
}

SeoSettings.init(
  {
    id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true,
    },
    page_type: {
      type: DataTypes.STRING(50),
      allowNull: false,
      validate: {
        notEmpty: {
          msg: "El tipo de página es requerido",
        },
        isIn: {
          args: [["global", "home", "products", "categories", "contact", "blog", "brands", "product", "category", "brand"]],
          msg: "Tipo de página no válido",
        },
      },
    },
    page_identifier: {
      type: DataTypes.STRING(255),
      allowNull: true,
      comment: "Identificador específico (slug, id, etc.)",
    },
    meta_title: {
      type: DataTypes.STRING(255),
      allowNull: true,
      validate: {
        len: {
          args: [0, 255],
          msg: "El título no puede tener más de 255 caracteres",
        },
      },
    },
    meta_description: {
      type: DataTypes.TEXT,
      allowNull: true,
      validate: {
        len: {
          args: [0, 500],
          msg: "La descripción no puede tener más de 500 caracteres",
        },
      },
    },
    meta_keywords: {
      type: DataTypes.TEXT,
      allowNull: true,
      comment: "Keywords separadas por comas",
    },
    og_title: {
      type: DataTypes.STRING(255),
      allowNull: true,
      comment: "Open Graph title",
    },
    og_description: {
      type: DataTypes.TEXT,
      allowNull: true,
      comment: "Open Graph description",
    },
    og_image: {
      type: DataTypes.STRING(500),
      allowNull: true,
      validate: {
        isUrl: {
          msg: "La URL de imagen de Open Graph debe ser válida",
        },
      },
    },
    twitter_title: {
      type: DataTypes.STRING(255),
      allowNull: true,
    },
    twitter_description: {
      type: DataTypes.TEXT,
      allowNull: true,
    },
    twitter_image: {
      type: DataTypes.STRING(500),
      allowNull: true,
      validate: {
        isUrl: {
          msg: "La URL de imagen de Twitter debe ser válida",
        },
      },
    },
    canonical_url: {
      type: DataTypes.STRING(500),
      allowNull: true,
      validate: {
        isUrl: {
          msg: "La URL canónica debe ser válida",
        },
      },
    },
    robots: {
      type: DataTypes.STRING(100),
      allowNull: false,
      defaultValue: "index,follow",
      validate: {
        isValidRobots(value: string) {
          const validDirectives = ["index", "noindex", "follow", "nofollow", "noarchive", "nosnippet", "noimageindex"];
          const directives = value.split(",").map((d) => d.trim());

          for (const directive of directives) {
            if (!validDirectives.includes(directive)) {
              throw new Error(`Directiva de robots no válida: ${directive}`);
            }
          }
        },
      },
    },
    schema_markup: {
      type: DataTypes.TEXT("long"),
      allowNull: true,
      comment: "JSON-LD schema markup",
      validate: {
        isValidJSON(value: string) {
          if (value) {
            try {
              JSON.parse(value);
            } catch (error) {
              throw new Error("El schema markup debe ser un JSON válido");
            }
          }
        },
      },
    },
    custom_head: {
      type: DataTypes.TEXT,
      allowNull: true,
      comment: "HTML personalizado para el head",
    },
    priority: {
      type: DataTypes.DECIMAL(2, 1),
      allowNull: false,
      defaultValue: 0.5,
      validate: {
        min: {
          args: [0.0],
          msg: "La prioridad debe ser entre 0.0 y 1.0",
        },
        max: {
          args: [1.0],
          msg: "La prioridad debe ser entre 0.0 y 1.0",
        },
      },
    },
    change_frequency: {
      type: DataTypes.ENUM("always", "hourly", "daily", "weekly", "monthly", "yearly", "never"),
      allowNull: false,
      defaultValue: "weekly",
    },
    is_active: {
      type: DataTypes.BOOLEAN,
      allowNull: false,
      defaultValue: true,
    },
    createdAt: {
      type: DataTypes.DATE,
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
    updatedAt: {
      type: DataTypes.DATE,
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    sequelize,
    modelName: "SeoSettings",
    tableName: "seo_settings",
    timestamps: true,
    indexes: [
      {
        unique: true,
        fields: ["page_type", "page_identifier"],
        name: "unique_page",
      },
      {
        fields: ["page_type"],
      },
      {
        fields: ["is_active"],
      },
      {
        fields: ["createdAt"],
      },
    ],
    hooks: {
      beforeValidate: (seoSettings: SeoSettings) => {
        // Limpiar espacios en blanco
        if (seoSettings.meta_title) seoSettings.meta_title = seoSettings.meta_title.trim();
        if (seoSettings.meta_description) seoSettings.meta_description = seoSettings.meta_description.trim();
        if (seoSettings.meta_keywords) seoSettings.meta_keywords = seoSettings.meta_keywords.trim();
        if (seoSettings.og_title) seoSettings.og_title = seoSettings.og_title.trim();
        if (seoSettings.og_description) seoSettings.og_description = seoSettings.og_description.trim();
        if (seoSettings.twitter_title) seoSettings.twitter_title = seoSettings.twitter_title.trim();
        if (seoSettings.twitter_description) seoSettings.twitter_description = seoSettings.twitter_description.trim();
        if (seoSettings.canonical_url) seoSettings.canonical_url = seoSettings.canonical_url.trim();
        if (seoSettings.robots) seoSettings.robots = seoSettings.robots.trim();
        if (seoSettings.custom_head) seoSettings.custom_head = seoSettings.custom_head.trim();
      },
    },
  }
);

export { SeoSettings, type SeoSettingsAttributes, type SeoSettingsCreationAttributes };

import { DataTypes, Model, Optional } from 'sequelize';
import { sequelize } from '../database/connection';

export interface SubCategoryAttributes {
  id: number;
  name: string;
  slug: string;
  category_id?: number | null;
  description?: string | null;
  order?: number;
  is_active?: boolean;
  created_at?: Date;
  updated_at?: Date;
}

export type SubCategoryCreationAttributes = Optional<
  SubCategoryAttributes,
  'id' | 'category_id' | 'order' | 'is_active' | 'created_at' | 'updated_at'
>;

export class SubCategory extends Model<SubCategoryAttributes, SubCategoryCreationAttributes> implements SubCategoryAttributes {
  public id!: number;
  public name!: string;
  public slug!: string;
  public category_id!: number | null;
  public description!: string | null;
  public order!: number;
  public is_active!: boolean;
  public readonly created_at!: Date;
  public readonly updated_at!: Date;

  // Relación con Category (se define en server.ts para evitar dependencias circulares)
  // Relación con Category (se define en server.ts para evitar dependencias circulares)
  public category?: any;

  public static generateSlug(name: string): string {
    if (!name) return '';
    return name
      .toString()
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  }
}

SubCategory.init(
  {
    id: {
      type: DataTypes.INTEGER,
      primaryKey: true,
      autoIncrement: true,
    },
    name: {
      type: DataTypes.STRING(255),
      allowNull: false,
    },
    slug: {
      type: DataTypes.STRING(255),
      allowNull: false,
      unique: true,
    },
    category_id: {
      type: DataTypes.INTEGER,
      allowNull: true,
      references: {
        model: 'categories',
        key: 'id'
      },
      onUpdate: 'CASCADE',
      onDelete: 'SET NULL',
      comment: 'Relación con la tabla categories'
    },
    description: {
      type: DataTypes.TEXT,
      allowNull: true,
    },
    order: {
      type: DataTypes.INTEGER,
      defaultValue: 0,
    },
    is_active: {
      type: DataTypes.BOOLEAN,
      defaultValue: true,
    },
    created_at: {
      type: DataTypes.DATE,
      defaultValue: DataTypes.NOW,
    },
    updated_at: {
      type: DataTypes.DATE,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    sequelize,
    tableName: 'sub_categories',
    timestamps: true,
    underscored: true,
  }
);

export default SubCategory;

import express, { Request, Response } from 'express';
import { body, validationResult } from 'express-validator';
import { User } from '../../models/User';
import { AuthController } from '../../controllers/authController';
import { authLimiter } from '../../middleware/rateLimiter';
import { authenticateToken, requireAdmin } from '../../middleware/authMiddleware';

const router = express.Router();

const validateRequest = (req: Request, res: Response, next: any) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Datos de entrada inválidos',
      details: errors.array()
    });
  }
  next();
};

// POST /api/admin/login - Login del administrador
router.post('/login', authLimiter, [
  body('email').isEmail().withMessage('Email válido es requerido'),
  body('password').notEmpty().withMessage('Contraseña es requerida'),
], validateRequest, AuthController.adminLogin);

// GET /api/admin/me - Información del usuario actual (requires auth)
router.get('/me', authenticateToken, requireAdmin, async (req: Request, res: Response) => {
  try {
    const user = await User.findByPk((req as Request & { user?: { id: number } }).user?.id);

    if (!user) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    res.json({
      user: {
        id: user.id,
        email: user.email,
        username: user.email.split('@')[0],
        firstName: user.first_name,
        lastName: user.last_name,
        role: user.role
      }
    });

  } catch (error) {
    res.status(401).json({ error: 'Token inválido' });
  }
});

export default router;

import express, { Request, Response } from 'express';
import { body, param, validationResult } from 'express-validator';
import multer from 'multer';
import path from 'path';
import fs from 'fs';
import { authenticateToken, requireAdmin } from '../../middleware/authMiddleware';
import { CarouselController } from '../../controllers/admin/CarouselController';

const router = express.Router();

// All routes require admin authentication, except the public /active endpoint (home carousel)
router.use((req, res, next) => {
    if (req.method === 'GET' && req.path === '/active') {
        return next();
    }
    authenticateToken(req, res, () => requireAdmin(req, res, next));
});

// Configuración de multer para subir imágenes
const uploadDir = path.join(__dirname, '../../../public/images/carousel');
if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        cb(null, uploadDir);
    },
    filename: (req, file, cb) => {
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, 'slide-' + uniqueSuffix + path.extname(file.originalname));
    }
});

const upload = multer({
    storage: storage,
    limits: {
        fileSize: 5 * 1024 * 1024 // 5MB max
    },
    fileFilter: (req, file, cb) => {
        const allowedTypes = /jpeg|jpg|png|gif|webp/;
        const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
        const mimetype = allowedTypes.test(file.mimetype);

        if (mimetype && extname) {
            return cb(null, true);
        } else {
            cb(new Error('Solo se permiten imágenes (jpeg, jpg, png, gif, webp)'));
        }
    }
});

// Middleware de validación
const validateRequest = (req: Request, res: Response, next: any) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            error: 'Datos de entrada inválidos',
            details: errors.array()
        });
    }
    next();
};

// GET todos los slides del carrusel
router.get('/', CarouselController.getAll);

// GET slides activos para el frontend
router.get('/active', CarouselController.getActive);

// PUT actualizar orden de slides
router.put('/reorder', [
    body('slides').isArray().withMessage('slides debe ser un array'),
    body('slides.*.id').isInt({ min: 1 }).withMessage('ID de slide debe ser un número entero mayor a 0'),
    body('slides.*.order').isInt({ min: 0 }).withMessage('Orden debe ser un número entero mayor o igual a 0'),
], validateRequest, CarouselController.reorder);

// POST subir imagen de carousel
router.post('/upload', upload.single('image'), CarouselController.uploadImage);

// GET slide por ID
router.get('/:id', [
    param('id').isInt({ min: 1 }).withMessage('ID debe ser un número entero mayor a 0'),
], validateRequest, CarouselController.getById);

// POST crear slide
router.post('/', [
    body('title').notEmpty().isLength({ min: 1, max: 200 }).withMessage('Título es requerido y debe tener entre 1 y 200 caracteres'),
    body('description').notEmpty().isLength({ min: 1, max: 1000 }).withMessage('Descripción es requerida y debe tener entre 1 y 1000 caracteres'),
    body('buttonText').notEmpty().isLength({ min: 1, max: 100 }).withMessage('Texto del botón es requerido y debe tener entre 1 y 100 caracteres'),
    body('buttonUrl').notEmpty().isString().withMessage('URL del botón es requerida y debe ser una cadena válida'),
    body('backgroundColor').optional().isLength({ max: 100 }).withMessage('Color de fondo no puede exceder 100 caracteres'),
    body('imageUrl').optional().isString().withMessage('URL de imagen debe ser una cadena válida'),
    body('isActive').optional().isBoolean().withMessage('isActive debe ser un booleano'),
    body('order').optional().isInt({ min: 0 }).withMessage('Orden debe ser un número entero mayor o igual a 0'),
], validateRequest, CarouselController.create);

// PUT actualizar slide
router.put('/:id', [
    param('id').isInt({ min: 1 }).withMessage('ID debe ser un número entero mayor a 0'),
    body('title').optional().isLength({ min: 1, max: 200 }).withMessage('Título debe tener entre 1 y 200 caracteres'),
    body('description').optional().isLength({ min: 1, max: 1000 }).withMessage('Descripción debe tener entre 1 y 1000 caracteres'),
    body('buttonText').optional().isLength({ min: 1, max: 100 }).withMessage('Texto del botón debe tener entre 1 y 100 caracteres'),
    body('buttonUrl').optional().isString().withMessage('URL del botón debe ser una cadena válida'),
    body('backgroundColor').optional().isLength({ max: 100 }).withMessage('Color de fondo no puede exceder 100 caracteres'),
    body('imageUrl').optional().isString().withMessage('URL de imagen debe ser una cadena válida'),
    body('isActive').optional().isBoolean().withMessage('isActive debe ser un booleano'),
    body('order').optional().isInt({ min: 0 }).withMessage('Orden debe ser un número entero mayor o igual a 0'),
], validateRequest, CarouselController.update);

// DELETE eliminar slide
router.delete('/:id', [
    param('id').isInt({ min: 1 }).withMessage('ID debe ser un número entero mayor a 0'),
], validateRequest, CarouselController.delete);

export default router;

