import express, { Request, Response } from 'express';
import multer from 'multer';
import path from 'path';
import fs from 'fs';
import { authenticateToken, requireAdmin } from '../../middleware/authMiddleware';
import { hasValidImageSignature } from '../../utils/imageSignature';
import { uploadLimiter } from '../../middleware/rateLimiter';
import { sendError } from '../../middleware/errorHandler';

const router = express.Router();

// All routes require admin authentication
router.use(authenticateToken, requireAdmin);

// Configurar almacenamiento
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        const uploadDir = path.join(__dirname, '../../../public/uploads');
        if (!fs.existsSync(uploadDir)) {
            fs.mkdirSync(uploadDir, { recursive: true });
        }
        cb(null, uploadDir);
    },
    filename: (req, file, cb) => {
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, uniqueSuffix + path.extname(file.originalname));
    }
});

const upload = multer({
    storage: storage,
    limits: { fileSize: 5 * 1024 * 1024 }, // 5MB límite
    fileFilter: (req, file, cb) => {
        const filetypes = /jpeg|jpg|png|webp|gif/;
        const mimetype = filetypes.test(file.mimetype);
        const extname = filetypes.test(path.extname(file.originalname).toLowerCase());

        if (mimetype && extname) {
            return cb(null, true);
        }
        cb(new Error('Solo se permiten imágenes (jpeg, jpg, png, webp, gif)'));
    }
});

// POST /upload - Subir un archivo
router.post('/', uploadLimiter, upload.single('image'), (req: Request, res: Response) => {
    try {
        if (!req.file) {
            return res.status(400).json({ error: 'No se subió ningún archivo' });
        }

        if (!hasValidImageSignature(req.file.path)) {
            fs.unlink(req.file.path, () => undefined);
            return res.status(400).json({ error: 'Archivo no es una imagen válida' });
        }

        // Construir URL pública
        const baseUrl = process.env.API_URL || 'http://localhost:3001';
        const imageUrl = `${baseUrl}/uploads/${req.file.filename}`;

        res.json({
            success: true,
            url: imageUrl,
            filename: req.file.filename
        });
    } catch (error: any) {
        return sendError(res, error, 'Error al subir archivo');
    }
});

export default router;

