        // Format description possibly with specs
        const description = item.product_name || item.product?.name || 'Producto desconocido';
        // Clean description needed?

        return [
          item.quantity.toFixed(3), // 1.000
          'UND', // Hardcoded unit
          item.product?.codigo_interno || item.product?.cod_producto || '-',
          description,
          (Number(item.product_price) || 0).toFixed(2),
          (Number(item.subtotal) || 0).toFixed(2)
        ];
      }),
      styles: {
        fontSize: 7,
        cellPadding: 2,
        valign: 'middle',
        lineWidth: 0.1,
        lineColor: [200, 200, 200]
      },
      headStyles: {
        fillColor: [220, 220, 220], // Light gray
        textColor: 0, // Black text
        fontStyle: 'bold',
        halign: 'center'
      },
      columnStyles: {
        0: { halign: 'center', cellWidth: 15 }, // Cantidad
        1: { halign: 'center', cellWidth: 10 }, // Und
        2: { halign: 'center', cellWidth: 15 }, // Codigo
        3: { halign: 'left' }, // Descripcion (Auto width)
        4: { halign: 'right', cellWidth: 20 }, // Unitario
        5: { halign: 'right', cellWidth: 20 }  // Total
      },
      theme: 'plain' // Removes default striping, we want simple borders
    });

    const finalY = (doc as any).lastAutoTable.finalY + 5;


    // --- FOOTER & TOTALS ---

    // Amount in words
    const totalAmount = typeof quotation.total === 'string' ? parseFloat(quotation.total) : quotation.total;
    const amountText = numberToWords(totalAmount);

    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.text(`SON: ${amountText}`, 10, finalY);

    const boxY = finalY + 5;

    // Totals Box (Right)
    const totalsX = 140;
    const totalsWidth = 60;
    const totalsLineH = 5;

    // Calculate totals
    const opGravada = totalAmount / 1.18;
    const igv = totalAmount - opGravada;

    doc.setDrawColor(200, 200, 200);
    // doc.rect(totalsX, boxY, totalsWidth, 20); // Box frame

    doc.text('Op. Gravada', totalsX + 2, boxY + totalsLineH);
    doc.text('S/', totalsX + 35, boxY + totalsLineH);
    doc.text(opGravada.toFixed(2), 195, boxY + totalsLineH, { align: 'right' });

    doc.text('IGV (18%)', totalsX + 2, boxY + totalsLineH * 2);
    doc.text('S/', totalsX + 35, boxY + totalsLineH * 2);
    doc.text(igv.toFixed(2), 195, boxY + totalsLineH * 2, { align: 'right' });

    doc.setFont('helvetica', 'bold');
    doc.text('Importe Total', totalsX + 2, boxY + totalsLineH * 3);
    doc.text('S/', totalsX + 35, boxY + totalsLineH * 3);
    doc.text(totalAmount.toFixed(2), 195, boxY + totalsLineH * 3, { align: 'right' });


    // Notes / Conditions (Left)
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.text('CONDICIONES DE VENTA: IGV Incluido - Sin otro Particular, quedamos de ustedes', 10, boxY + 20);

    // Sales Assitant
    doc.setFontSize(8);
    doc.text('VENDEDOR(A): SISTEMA WEB', 130, boxY + 30);
    doc.setFontSize(7);
    doc.text('Observacion: Sujeta a variación de precios', 130, boxY + 34);

    return Buffer.from(doc.output('arraybuffer'));
  }
}

import fs from 'fs';
import { Op } from 'sequelize';
import { Product } from '../models/Product';
import { PeruanaInformaticaService } from './PeruanaInformaticaService';
import { logger } from '../config/logger';

export class SyncService {
    private static isSyncing = false;
    private static lastSyncTime = 0;
    private static SYNC_INTERVAL_MS = 30 * 60 * 1000; // 30 minutes cooldown

    static async syncProducts() {
        // Prevent concurrent syncs and respect cooldown
        const now = Date.now();
        if (this.isSyncing || (now - this.lastSyncTime < this.SYNC_INTERVAL_MS)) {
            // Debug log to know why it skipped
            // logger.info(`SyncService: Skipped. Syncing: ${this.isSyncing}, Cooldown: ${((this.SYNC_INTERVAL_MS - (now - this.lastSyncTime)) / 1000).toFixed(0)}s remaining`);
            return { skipped: true, reason: this.isSyncing ? 'Sync in progress' : 'Cooldown active' };
        }

        this.isSyncing = true;
        let updatedCount = 0;
        let errorCount = 0;

        try {
            logger.info('SyncService: Starting synchronization with External API...');

            // Get all active products with an internal code
            const products = await Product.findAll({
                where: {
                    codigo_interno: { [Op.ne]: null as any },
                    is_active: 1
                }
            });

            logger.info(`SyncService: Found ${products.length} products to sync.`);

            // Process sequentially to avoid overwhelming the external API
            for (const product of products) {
                if (!product.codigo_interno) continue;

                try {
                    // Slight delay to be nice to the API
                    await new Promise(resolve => setTimeout(resolve, 200));

                    // Use centralized service logic to get active data
                    const syncData = await PeruanaInformaticaService.obtenerStockYPrecio(product.codigo_interno);

                    if (syncData) {
                        // Check if prices or stock changed
                        // SyncService maps:
                        // pre_cli -> price (Precio Base)
                        // pre_web -> price_web (Precio Online)
                        // pre_cot -> price_cot
                        // pre_dis -> price_dis

                        const newPrice = syncData.pre_cli;
                        const newPriceWeb = syncData.pre_web;
                        const newPriceCot = syncData.pre_cot;
                        const newPriceDis = syncData.pre_dis;
                        const newStock = syncData.stock;

                        if (product.codigo_interno === '15953') {
                            logger.info(`[SYNC DEBUG 15953] DB: Cli=${product.price}, Web=${product.price_web}, Dis=${product.price_dis}`);
                            logger.info(`[SYNC DEBUG 15953] API: Cli=${newPrice}, Web=${newPriceWeb}, Dis=${newPriceDis}`);
                        }

                        if (
                            Number(product.price) !== newPrice ||
                            Number(product.price_web) !== newPriceWeb ||
                            Number(product.price_cot) !== newPriceCot ||
                            Number(product.price_dis) !== newPriceDis ||
                            product.stock !== newStock
                        ) {
                            await product.update({
                                price: newPrice,
                                price_web: newPriceWeb,
                                price_cot: newPriceCot,
                                price_dis: newPriceDis,
                                stock: newStock
                            });
                            updatedCount++;
                            // logger.info(`SyncService: Updated ${product.codigo_interno}: Stock=${newStock}, Web=${newPriceWeb}`);
                        }
                    } else {
                        // Product not found in API or error
                        // logger.warn(`SyncService: Data not found for ${product.codigo_interno}`);
                        errorCount++;
                    }
                } catch (err: any) {
                    logger.error(`SyncService: Error syncing product ${product.codigo_interno}`, err.message);
                    errorCount++;
                }
            }

            this.lastSyncTime = Date.now();
            logger.info(`SyncService: Sync completed. ${updatedCount} products updated. ${errorCount} errors.`);
            return { success: true, updated: updatedCount, errors: errorCount };

        } catch (error) {
            logger.error('SyncService: Fatal error', error);
            return { error: 'Sync failed' };
        } finally {
            this.isSyncing = false;
        }
    }
}

import { Transaction } from 'sequelize';
import { Product } from '../models/Product';
import { Image } from '../models/Image';
import { ProductSubCategory } from '../models/ProductSubCategory';

export async function createProductRecord(data: any, transaction: Transaction) {
        const {
            name,
            description,
            price,
            stock,
            category_id,
            brand_id,
            image,
            keywords,
            component_type,
            additional_images,
            subcategory_ids
        } = data;

        const baseSlug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
        let slug = baseSlug;
        let counter = 1;

        while (await Product.findOne({ where: { slug }, transaction })) {
            slug = `${baseSlug}-${counter}`;
            counter++;
        }

        const generateCodigoInterno = async (): Promise<string> => {
            const timestamp = Date.now().toString().slice(-8);
            const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
            const codigo = `${timestamp}${random}`;

            const exists = await Product.findOne({ where: { codigo_interno: codigo }, transaction });
            if (exists) {
                return generateCodigoInterno();
            }
            return codigo;
        };

        let codigo_interno: string;
        const providedCodigo = data.codigo_interno;

        if (providedCodigo !== undefined && providedCodigo !== null && String(providedCodigo).trim() !== '') {
            codigo_interno = String(providedCodigo).trim();

            const duplicate = await Product.findOne({ where: { codigo_interno }, transaction });
            if (duplicate) {
                const duplicateError: any = new Error(`El código interno '${codigo_interno}' ya está registrado`);
                duplicateError.code = 'DUPLICATE_CODIGO_INTERNO';
                throw duplicateError;
            }
        } else {
            codigo_interno = await generateCodigoInterno();
        }

        const product = await Product.create({
            name,
            slug,
            description,
            short_description: (description || '').substring(0, 500),
            price,
            stock,
            category_id,
            brand_id,
            image,
            keywords,
            codigo_interno,
            seo_title: data.seo_title ?? null,
            seo_description: data.seo_description ?? null,
            component_type: component_type || null
        }, { transaction });

        if (additional_images && additional_images.length > 0) {
            await Image.bulkCreate(
                additional_images.map((imgUrl: string) => ({
                    codigo_interno: product.codigo_interno,
                    imagen: imgUrl
                })),
                { transaction }
            );
        }

        if (subcategory_ids && Array.isArray(subcategory_ids) && subcategory_ids.length > 0) {
            const subcategoryRecords = subcategory_ids.map((subId: number) => ({
                product_codigo_interno: product.codigo_interno,
                sub_category_id: subId
            }));
            await ProductSubCategory.bulkCreate(subcategoryRecords, { transaction });
        }

        return product;
    }

